_setFocusTrap() {
  if (this._focusTrapHandler) {
    return
  }
  this._focusTrapHandler = event => {
    if (event.key !== 'Tab') {
      return
    }
    const focusableElements = this._element.querySelectorAll(
      'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
    )
    if (focusableElements.length === 0) {
      return
    }
    const firstElement = focusableElements[0]
    const lastElement = focusableElements[focusableElements.length - 1]
    const activeElement = document.activeElement
    if (event.shiftKey) {
      if (activeElement === firstElement) {
        event.preventDefault()
        lastElement.focus()
      }
    } else {
      if (activeElement === lastElement) {
        event.preventDefault()
        firstElement.focus()
      }
    }
  }
  EventHandler.on(this._element, 'keydown', this._focusTrapHandler)
}

_removeFocusTrap() {
  if (this._focusTrapHandler) {
    EventHandler.off(this._element, 'keydown', this._focusTrapHandler)
    this._focusTrapHandler = null
  }
}

